(* [comment removed for export] *)
Lemma RIL_leaf R1 R2 (ks : list nat) q flag q' flag' :
  RIL R1 q flag -> (forall j, In j ks -> getr R2 (reg j) = getr R1 (reg j)) ->
  inks [2; 8; 9; 19; 20; 22; 23; 24; 25; 26; 3; 4; 27]%nat ks = true ->
  getr R2 (reg 18) = Z_to_bv 64 q' -> getr R2 (reg 21) = Z_to_bv 64 flag' -> RIL R2 q' flag'.
