Section Iter.
Variable i : Z.
Hypothesis Hi : 0 <= i < n.
Hypothesis HK : i + 1 < n -> forall (p' flag' : Z) (fx2 : FPState) (R2 : bvmap 5 word) (M2 : word -> option byte) (model2 : Model) (x2 : sst) (cr2 : credit),
   INV p' M2 model2 x2 cr2 -> 0 <= p' <= i + 1 -> 0 <= flag' <= 1 -> RIL R2 (buf + (i + 1)) flag' ->
   srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 0x3d6c4 M2 model2) K.

(* [comment removed for export] *)
Lemma NEXT (p flag : Z) (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (x1 : sst) (cr1 : credit) :
  INV p M1 model1 x1 cr1 -> 0 <= p <= i + 1 -> 0 <= flag <= 1 -> RIL R1 (buf + i) flag ->
