Definition c_unit (t : Z) : bool := (48 <=? e_unit t (t / 10)) && (e_unit t (t / 10) <=? 57).
Lemma unit_ok t : 0 <= t <= 99 -> 48 <= e_unit t (t / 10) <= 57.
