Import PMS.
Local Ltac lia := L5FastLia.plia.
Abbreviation reg i := (Z_to_bv 5 (Z.of_nat i)).
Abbreviation mst fx R pc M := (@mkst fx R (Z_to_bv 64 pc) M (seg_rom RSEGS)).

Section WithHeap.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis LY : PMS.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Let KL := PMKS.klayout_S L LY.
Let SF := PMKS.sfoot_S L LY.
Variable sst : Type.
Variable str_at : (word -> option byte) -> Z -> sst -> Prop.
Variable str_own : sst -> list (Z * Z).
Variable str_size : sst -> Z.
Variable str_pot : sst -> credit.
Hypothesis STR_KEEP : forall (M M' : word -> option byte) os x, 0 <= os -> os + 24 <= 2 ^ 64 -> mem_grows M M' -> L5C.agree_on M M' os 24 -> str_at M os x -> str_at M' os x.
Hypothesis PB : WD.push_back_spec RSEGS AD L HI sst str_at str_own str_size str_pot 0x66444.

Section Call.
Variables (M0 : word -> option byte) (model0 : Model) (K : TSet) (LBX : list (Z * Z)) (cr0 : credit).
Variables (so os sp r s0v s1v s2v : Z) (x0 : sst) (SCR MAX : Z).
Hypothesis K0 : K [].
Hypothesis Hso1 : sp <= so.
Hypothesis Hso2 : so + 8 <= hl_sptop L.
Hypothesis Hos1 : sp <= os.
Hypothesis Hos2 : os + 24 <= hl_sptop L.
Hypothesis APT : WD.apart24 so 8 os.
Hypothesis CR0 : PMSP.credit_le (str_pot x0) cr0.
Hypothesis SZ0 : str_size x0 + MAX <= WD.STR_MAX.
Hypothesis BRX : PMFR.brange L LBX.
Hypothesis HSCR : WD.PB_SCR + 32 <= SCR.

(* [comment removed for export] *)
Definition inv (n : Z) (M : word -> option byte) (model : Model) (x : sst) (cr : credit) : Prop :=
  hi_heap HI (str_own x ++ LBX) cr M (m_vmmaps model) /\ PMSP.model_ok model /\
  L5C.stk (hl_sptop L) M sp SCR /\ str_at M os x /\ str_size x = str_size x0 + n /\
  L5.u64_at RSEGS M so os /\
  L5.u64_at RSEGS M (sp - 8) r /\ L5.u64_at RSEGS M (sp - 16) s0v /\ L5.u64_at RSEGS M (sp - 24) s1v /\ L5.u64_at RSEGS M (sp - 32) s2v /\
  PMST.base_ok RSEGS AD M /\ PMSP.credit_keep cr0 cr (str_pot x0) (str_pot x) /\
  PMK.ek L LBX sp SCR [(os, 24)] M0 M /\ PMK.dk L LBX sp SCR M0 M /\ model_but_vm model0 model.

Lemma CALL (n c ra1 : Z) (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (x : sst) (cr : credit) :
  inv n M model x cr -> 0 <= n < MAX ->
  getr R (reg 1) = Z_to_bv 64 ra1 -> L5.ra_ok ra1 -> getr R (reg 2) = Z_to_bv 64 (sp - 32) ->
  getr R (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R (reg 4) = Z_to_bv 64 (pa_tp AD) ->
  getr R (reg 10) = Z_to_bv 64 os -> getr R (reg 11) = Z_to_bv 64 c -> 0 <= c < 256 ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (x' : sst) (cr' : credit),
      regs_preserved R R' -> inv (n + 1) M' model' x' cr' -> srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' ra1 M' model') K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x66444 M model) K.
