(* [comment removed for export] *)
Lemma FIN (n c : Z) (fx1 : FPState) (R1 R2 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (x1 : sst) (cr1 : credit) (ks : list nat) :
  INV n M1 model1 x1 cr1 -> 0 <= n < 4 -> RI R1 ->
  (forall j, In j ks -> getr R2 (reg j) = getr R1 (reg j)) ->
  forallb (fun j => existsb (Nat.eqb j) ks) [3; 4; 19; 20; 21; 22; 23; 24; 25; 26; 27]%nat = true ->
  getr R2 (reg 1) = Z_to_bv 64 r -> getr R2 (reg 2) = Z_to_bv 64 sp ->
  getr R2 (reg 8) = Z_to_bv 64 s0v -> getr R2 (reg 9) = Z_to_bv 64 s1v -> getr R2 (reg 18) = Z_to_bv 64 s2v ->
  getr R2 (reg 10) = Z_to_bv 64 os -> getr R2 (reg 11) = Z_to_bv 64 c -> 0 <= c < 256 ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R2 0x66444 M1 model1) K.
