Lemma STEP_E (n kk : Z) (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (x1 : sst) (cr1 : credit) :
  INV n M1 model1 x1 cr1 -> 0 <= n < 3 -> RI R1 -> getr R1 (reg 9) = Z_to_bv 64 kk -> 100 <= kk <= 999 -> getr R1 (reg 18) = Z_to_bv 64 (kk / 100) ->
