(* [comment removed for export] *)
Definition VM (p c m i : Z) : nat -> Z := fun j =>
  match j with 2%nat => sp | 33%nat => os | 34%nat => so | 35%nat => r | 36%nat => sv 8 | 37%nat => sv 9 | 38%nat => sv 18 | 39%nat => sv 19 | 40%nat => sv 20 | 41%nat => sv 21
  | 50%nat => buf | 51%nat => len | 52%nat => ku | 53%nat => kku | 54%nat => p | 56%nat => c | 57%nat => m | 58%nat => i | _ => 0 end.

Local Ltac facts IV :=
  pose proof (inv_facts _ _ _ _ _ IV) as (Mh & Ml & WR & FLO & SHI & STOP & A16 & CSO & BD & D8 & D16 & D24 & D32 & D40 & D48 & D56);
  pose proof (svr 8) as S8; pose proof (svr 9) as S9; pose proof (svr 18) as S18; pose proof (svr 19) as S19; pose proof (svr 20) as S20; pose proof (svr 21) as S21;
  pose proof KUr as KU2; pose proof KKUr as KKU2; pose proof RAok as (Hr1 & Hr2).
Local Ltac piece P := cbn beta iota delta [VM] in P; unfold VDSPRP.aligned in P; PMK.feed P ltac:(first [PMK.sc]).
Local Ltac pure FR2 M2 := assert (EM2 : M2 = _) by (apply functional_extensionality; exact FR2); subst M2.

