(* [comment removed for export] *)
Lemma EK (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (x1 : sst) (cr1 : credit) :
  INV 1 M1 model1 x1 cr1 -> RC R1 -> getr R1 (reg 9) = Z_to_bv 64 len -> getr R1 (reg 18) = Z_to_bv 64 buf -> getr R1 (reg 20) = Z_to_bv 64 kku ->
  (18 <= k + len \/ k + len <= -4) ->
