  Z.of_nat m = k + len - 1 - i -> 0 <= i < k + len -> INV p M1 model1 x1 cr1 -> p = i -> RC R1 ->
  getr R1 (reg 18) = Z_to_bv 64 (buf + i) -> getr R1 (reg 21) = Z_to_bv 64 (buf + (k + len)) -> getr R1 (reg 9) = Z_to_bv 64 len ->
  getr R1 (reg 19) = Z_to_bv 64 ku -> getr R1 (reg 20) = Z_to_bv 64 kku ->
  getr R1 (reg 1) = Z_to_bv 64 0x3dd8c -> getr R1 (reg 10) = Z_to_bv 64 os -> getr R1 (reg 11) = Z_to_bv 64 c -> 0 <= c < 256 ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x66444 M1 model1) K.
