Lemma TAIL (n c : Z) (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (x : sst) (cr : credit) :
  inv n M model x cr -> 0 <= n < MAX ->
  getr R (reg 1) = Z_to_bv 64 r -> L5.ra_ok r -> getr R (reg 2) = Z_to_bv 64 sp ->
  getr R (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R (reg 4) = Z_to_bv 64 (pa_tp AD) ->
  getr R (reg 10) = Z_to_bv 64 os -> getr R (reg 11) = Z_to_bv 64 c -> 0 <= c < 128 ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (x' : sst) (cr' : credit),
      regs_preserved R R' -> str_at M' os x' -> str_size x0 <= str_size x' <= str_size x0 + MAX ->
      (exists ds, str_txt x' = str_txt x0 ++ ds /\ VDC.ascii ds) ->
      L5C.hpres L LBX sp SCR [(os, 24)] M0 M' -> PMSP.credit_keep cr0 cr' (str_pot x0) (str_pot x') ->
      model_but_vm model0 model' -> hi_heap HI (str_own x' ++ LBX) cr' M' (m_vmmaps model') ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x66444 M model) K.
