  (forall j, In j ks -> getr R2 (reg j) = getr R1 (reg j)) ->
  forallb (fun j => existsb (Nat.eqb j) ks) [3; 4; 19; 20; 21; 22; 23; 24; 25; 26; 27]%nat = true ->
