  INV p M1 model1 x1 cr1 -> 0 <= p <= 27 ->
  getr R1 (reg 1) = Z_to_bv 64 r -> getr R1 (reg 2) = Z_to_bv 64 sp ->
  (forall j, In j [8; 9; 18; 19; 20; 21]%nat -> getr R1 (reg j) = Z_to_bv 64 (sv j)) ->
  (forall j, In j KEPT -> getr R1 (reg j) = getr R (reg j)) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x3de4c M1 model1) K.
