Lemma L4K (m : nat) : forall (i p c : Z) (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (x1 : sst) (cr1 : credit),
  Z.of_nat m = len - 1 - i -> k + len <= i < len -> INV p M1 model1 x1 cr1 -> p = i + 1 -> RC R1 ->
  getr R1 (reg 20) = Z_to_bv 64 i -> getr R1 (reg 21) = Z_to_bv 64 (buf + i) -> getr R1 (reg 9) = Z_to_bv 64 len ->
  getr R1 (reg 1) = Z_to_bv 64 0x3ddb0 -> getr R1 (reg 10) = Z_to_bv 64 os -> getr R1 (reg 11) = Z_to_bv 64 c -> 0 <= c < 128 ->
